const TIER_STYLES = {
  'Grand Prix': { bg: '#D4FF3D', fg: '#0A0A0A', label: 'GRAND PRIX' },
  'Gold':       { bg: '#E8C547', fg: '#0A0A0A', label: 'GOLD' },
  'Silver':     { bg: '#C9CDD3', fg: '#0A0A0A', label: 'SILVER' },
  'Bronze':     { bg: '#C97B4A', fg: '#0A0A0A', label: 'BRONZE' },
  'Unranked':   { bg: '#555', fg: '#fff', label: '' },
};

const DECK_SIZE = 16;

function getEmbed(url) {
  try {
    const u = new URL(url);
    if (u.hostname.includes('youtube.com') && u.searchParams.get('v')) {
      return { type: 'youtube', id: u.searchParams.get('v') };
    }
    if (u.hostname === 'youtu.be') {
      return { type: 'youtube', id: u.pathname.slice(1) };
    }
    if (u.hostname.includes('vimeo.com')) {
      const parts = u.pathname.split('/').filter(Boolean);
      const id = parts.find(p => /^\d+$/.test(p));
      if (id) return { type: 'vimeo', id };
    }
  } catch (e) {}
  return null;
}

function shuffleArray(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function buildDeck(pool, size) {
  const shuffled = shuffleArray(pool);
  return shuffled.slice(0, Math.min(size, shuffled.length));
}

export default function App() {
  const [tierFilter, setTierFilter] = useState('All');
  const pool = useMemo(() => {
    return tierFilter === 'All' ? DATA : DATA.filter(c => c.t === tierFilter);
  }, [tierFilter]);

  const [deck, setDeck] = useState(() => buildDeck(pool, DECK_SIZE));
  const [cursor, setCursor] = useState(0);
  const [saved, setSaved] = useState([]);
  const [showVideo, setShowVideo] = useState(false);
  const [view, setView] = useState('swipe'); // 'swipe' | 'saved' | 'done'
  const [drag, setDrag] = useState({ x: 0, active: false });
  const startX = useRef(0);
  const cardRef = useRef(null);
  const [exitDir, setExitDir] = useState(null);
  const [savedIdx, setSavedIdx] = useState(0);

  const current = deck[cursor];
  const embed = useMemo(() => current ? getEmbed(current.u) : null, [current]);
  const tierStyle = current ? (TIER_STYLES[current.t] || TIER_STYLES.Unranked) : TIER_STYLES.Unranked;

  const advance = useCallback((liked) => {
    if (liked && current) {
      setSaved(s => (s.find(x => x.u === current.u) ? s : [...s, current]));
    }
    setShowVideo(false);
    setExitDir(liked ? 1 : -1);
    setTimeout(() => {
      setExitDir(null);
      setDrag({ x: 0, active: false });
      if (cursor + 1 >= deck.length) {
        setView('done');
      } else {
        setCursor(c => c + 1);
      }
    }, 220);
  }, [current, cursor, deck.length]);

  const onPointerDown = (e) => {
    startX.current = e.clientX ?? ((e.touches && e.touches[0].clientX) || 0);
    setDrag({ x: 0, active: true });
  };
  const onPointerMove = (e) => {
    if (!drag.active) return;
    const x = (e.clientX ?? (e.touches && e.touches[0].clientX)) - startX.current;
    setDrag({ x, active: true });
  };
  const onPointerUp = () => {
    if (!drag.active) return;
    if (drag.x > 100) {
      advance(true);
    } else if (drag.x < -100) {
      advance(false);
    } else {
      setDrag({ x: 0, active: false });
    }
  };

  const newSession = useCallback((tier) => {
    const nextPool = tier === 'All' ? DATA : DATA.filter(c => c.t === tier);
    setDeck(buildDeck(nextPool, DECK_SIZE));
    setCursor(0);
    setShowVideo(false);
    setDrag({ x: 0, active: false });
    setExitDir(null);
    setView('swipe');
  }, []);

  const onTierChange = (t) => {
    setTierFilter(t);
    newSession(t);
  };

  const rotation = drag.x / 18;
  const cardStyle = {
    ...styles.card,
    transform: exitDir
      ? `translateX(${exitDir * 500}px) rotate(${exitDir * 24}deg)`
      : `translateX(${drag.x}px) rotate(${rotation}deg)`,
    transition: exitDir ? 'transform 0.22s ease-in' : (drag.active ? 'none' : 'transform 0.25s cubic-bezier(.2,.8,.3,1)'),
    opacity: exitDir ? 0 : 1,
  };

  const likeOpacity = Math.max(0, Math.min(1, drag.x / 100));
  const skipOpacity = Math.max(0, Math.min(1, -drag.x / 100));

  if (view === 'saved') {
    const s = saved[savedIdx];
    const sEmbed = s ? getEmbed(s.u) : null;
    const sTier = s ? (TIER_STYLES[s.t] || TIER_STYLES.Unranked) : TIER_STYLES.Unranked;
    return (
      <div style={styles.page}>
        <style>{globalCss}</style>
        <header style={styles.header}>
          <button style={styles.backTextBtn} onClick={() => setView('swipe')}>← BACK</button>
          <div style={styles.brandSub}>YOUR SHELF</div>
          <div style={{width:60}} />
        </header>
        {saved.length === 0 ? (
          <div style={styles.emptyState}>
            <p style={styles.emptyText}>Nothing saved yet.<br/>Swipe right on what you love.</p>
          </div>
        ) : (
          <>
            <main style={styles.main}>
              <div style={styles.cardStatic}>
                <div style={styles.cardTop}>
                  <span style={{...styles.tierBadge, background: sTier.bg, color: sTier.fg}}>{sTier.label}</span>
                  <span style={styles.yearBadge}>{s.y}</span>
                </div>
                <div style={styles.mediaArea}>
                  {sEmbed ? (
                    <iframe style={styles.iframe} src={sEmbed.type === 'youtube' ? `https://www.youtube.com/embed/${sEmbed.id}` : `https://player.vimeo.com/video/${sEmbed.id}`} title={s.ti} frameBorder="0" allow="accelerometer; autoplay; encrypted-media; picture-in-picture" allowFullScreen />
                  ) : (
                    <a href={s.u} target="_blank" rel="noopener noreferrer" style={styles.playWrap}>
                      <div style={styles.playCircle}><div style={styles.playTriangle} /></div>
                      <span style={styles.playLabel}>VIEW WORK ↗</span>
                    </a>
                  )}
                </div>
                <div style={styles.textArea}>
                  <h1 style={styles.title}>{s.ti}</h1>
                  <p style={styles.brand}>{s.b}</p>
                  <p style={styles.agency}>{s.a}</p>
                </div>
              </div>
            </main>
            <footer style={styles.savedFooter}>
              <button style={styles.iconBtn2} onClick={() => setSavedIdx(i => Math.max(0, i - 1))} disabled={savedIdx === 0}>←</button>
              <span style={styles.savedCounter}>{savedIdx + 1} / {saved.length}</span>
              <button style={styles.iconBtn2} onClick={() => setSavedIdx(i => Math.min(saved.length - 1, i + 1))} disabled={savedIdx === saved.length - 1}>→</button>
            </footer>
          </>
        )}
      </div>
    );
  }

  if (view === 'done' || !current) {
    return (
      <div style={styles.page}>
        <style>{globalCss}</style>
        <header style={styles.header}>
          <div style={styles.brandRow}>
            <span style={styles.brandMark}>LTWM</span>
            <span style={styles.brandSub}>SHUFFLE</span>
          </div>
        </header>
        <div style={styles.emptyState}>
          <p style={styles.doneEmoji}>✓</p>
          <p style={styles.emptyText}>That's today's stack.<br/>You saved {saved.length} of {deck.length}.</p>
          <button style={styles.shuffleBtn} onClick={() => newSession(tierFilter)}>NEW STACK</button>
          {saved.length > 0 && (
            <button style={styles.textLink} onClick={() => { setSavedIdx(0); setView('saved'); }}>View your shelf →</button>
          )}
        </div>
      </div>
    );
  }

  return (
    <div style={styles.page}>
      <style>{globalCss}</style>

      <header style={styles.header}>
        <div style={styles.brandRow}>
          <span style={styles.brandMark}>LTWM</span>
          <span style={styles.brandSub}>SHUFFLE</span>
        </div>
        <button style={styles.shelfBtn} onClick={() => { setSavedIdx(Math.max(0, saved.length-1)); setView('saved'); }}>
          ♥ {saved.length}
        </button>
      </header>

      <div style={styles.filterRow}>
        {['All','Grand Prix','Gold','Silver','Bronze'].map(t => (
          <button
            key={t}
            onClick={() => onTierChange(t)}
            style={{
              ...styles.filterChip,
              background: tierFilter === t ? '#D4FF3D' : 'transparent',
              color: tierFilter === t ? '#0A0A0A' : '#D4FF3D',
              borderColor: '#D4FF3D',
            }}
          >
            {t === 'All' ? 'ALL' : TIER_STYLES[t].label}
          </button>
        ))}
      </div>

      <div style={styles.progressRow}>
        <div style={styles.progressTrack}>
          <div style={{...styles.progressFill, width: `${((cursor)/deck.length)*100}%`}} />
        </div>
        <span style={styles.progressLabel}>{cursor + 1} / {deck.length}</span>
      </div>

      <main style={styles.main}>
        <div style={styles.stackWrap}>
          {deck[cursor+1] && (
            <div style={styles.cardBehind}>
              <div style={styles.mediaAreaBehind} />
            </div>
          )}
          <div
            ref={cardRef}
            style={cardStyle}
            onMouseDown={onPointerDown}
            onMouseMove={onPointerMove}
            onMouseUp={onPointerUp}
            onMouseLeave={onPointerUp}
            onTouchStart={onPointerDown}
            onTouchMove={onPointerMove}
            onTouchEnd={onPointerUp}
          >
            <div style={{...styles.stamp, ...styles.stampLike, opacity: likeOpacity}}>SAVE</div>
            <div style={{...styles.stamp, ...styles.stampSkip, opacity: skipOpacity}}>SKIP</div>

            <div style={styles.cardTop}>
              <span style={{...styles.tierBadge, background: tierStyle.bg, color: tierStyle.fg}}>
                {tierStyle.label}
              </span>
              <span style={styles.yearBadge}>{current.y}</span>
            </div>

            <div style={styles.mediaArea}>
              {showVideo && embed ? (
                embed.type === 'youtube' ? (
                  <iframe style={styles.iframe} src={`https://www.youtube.com/embed/${embed.id}?autoplay=1`} title={current.ti} frameBorder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen />
                ) : (
                  <iframe style={styles.iframe} src={`https://player.vimeo.com/video/${embed.id}?autoplay=1`} title={current.ti} frameBorder="0" allow="autoplay; fullscreen; picture-in-picture" allowFullScreen />
                )
              ) : (
                <button
                  style={styles.playWrap}
                  onClick={() => embed ? setShowVideo(true) : window.open(current.u, '_blank')}
                >
                  <div style={styles.playCircle}>
                    <div style={styles.playTriangle} />
                  </div>
                  <span style={styles.playLabel}>{embed ? 'TAP TO WATCH' : 'VIEW WORK ↗'}</span>
                </button>
              )}
            </div>

            <div style={styles.textArea}>
              <h1 style={styles.title}>{current.ti}</h1>
              <p style={styles.brand}>{current.b}</p>
              <p style={styles.agency}>{current.a}</p>
            </div>
          </div>
        </div>
      </main>

      <footer style={styles.footer}>
        <button className="icon-btn" onClick={() => advance(false)} style={styles.skipBtn} aria-label="Skip">✕</button>
        <span style={styles.swipeHint}>swipe or tap</span>
        <button className="icon-btn" onClick={() => advance(true)} style={styles.saveBtn} aria-label="Save">♥</button>
      </footer>
    </div>
  );
}

